/** Auto Charge Berserker: a kill-based bank addition, separate from the card's
 * damage-taken fraction. Existing knowledge contract: vault.harmonyTree and
 * vault.harmonyTree -> damage.berserker, sourced to The Vault/Harmony Tree.
 * https://the-tower.notion.site/Auto-Charge-Berserker-1dc91383b93f80d7935ee6d6ab61ac7f
 * The public description verifies automation; the numeric coefficient remains
 * the SDK's wiki-derived knowledge, not a newly recovered native callback.
 */
export const BERSERKER_VAULT_KILL_CHARGE_FRACTION = 0.001

/** Bonus damage banked per kill from the supplied unmodified enemy damage stat. */
export function berserkerKillChargeBonus(enemyDamage: number): number {
  if (!Number.isFinite(enemyDamage) || enemyDamage < 0)
    throw new Error('BERSERKER_KILL_CHARGE_ENEMY_DAMAGE_INVALID')
  return enemyDamage * BERSERKER_VAULT_KILL_CHARGE_FRACTION
}
